    {
      "name": "User",
      "fields": ["username", "password", "email", "role"]
    },
    {
      "name": "Plan",
      "fields": ["name", "price", "features"]
    }
  ],
  "roles": ["admin", "member"],
  "features": ["auth", "dashboard", "roleBasedAccess", "payments", "analytics"],
  "hasAuth": true,
  "hasPayments": true,
  "ambiguities": [],
